1	import type { Agent } from './agent';
2	import type { Belief } from './beliefs';
3	import type { WorldEvent } from './cg-types';
4	import type { LocationGraph } from './world-types';
5	import type { TimePeriod } from './schedule';
6	import { getEventLabelSafe, isTransferable, isStatusAbsent } from './event-registry';
7	import type { NpcFilter } from './goals';
8	
9	// ─── Affordance Data Model ───
10	
11	export interface AffordanceRequirement {
12	  /** Allowed time periods (undefined = any time) */
13	  period?: TimePeriod[];
14	  /** No guard NPC at the target's location */
15	  noGuardNearby?: boolean;
16	  /** Maximum number of other NPCs at location (undefined = no limit) */
17	  maxWitnesses?: number;
18	  /** Target must have a shop */
19	  /** NPC must have a crime belief about someone (confidence >= threshold) */
20	  hasCrimeBelief?: boolean;
21	  /** Minimum confidence for crime belief */
22	  beliefConfidence?: number;
23	  /** NPC mood must be below this threshold */
24	  moodBelow?: number;
25	  /** NPC sentiment toward target must be below this */
26	  sentimentBelow?: number;
27	  /** NPC must NOT be a guard */
28	  notGuard?: boolean;
29	  /** NPC must be a guard */
30	  isGuard?: boolean;
31	  /** NPC must have investigator flag */
32	  isInvestigator?: boolean;
33	  /** NPC must be the criminal (subject of NPC_KILLED/GOODS_STOLEN event matching their name) */
34	  isCriminal?: boolean;
35	  /** NPC must be wanted (WANTED_STATUS event exists for them) */
36	  isWanted?: boolean;
37	  /** A detained NPC must exist somewhere */
38	  hasDetainedNpc?: boolean;
39	  /** NPC must have a witness belief that someone else doesn't know about */
40	  hasWitnessBelief?: boolean;
41	  /** NPC must NOT be a perpetrator of any crime (has no guilt-source beliefs) */
42	  notPerpetrator?: boolean;
43	  /** NPC must have canSentence capability (judges, magistrates) */
44	  canSentence?: boolean;
45	  /** NPC must have suspicion belief (for surveillance) */
46	  hasSuspicionBelief?: boolean;
47	  /** NPC deduction confidence must be below threshold (for investigate vs arrest) */
48	  deductionBelowThreshold?: boolean;
49	}
50	
51	export type OceanHTrait = 'O' | 'C' | 'E' | 'A' | 'N' | 'H';
52	
53	export interface AffordanceWeight {
54	  trait: OceanHTrait;
55	  /** 'high' = use trait value directly, 'low' = use (1 - trait) */
56	  direction: 'high' | 'low';
57	  /** Multiplier for this personality factor */
58	  multiplier: number;
59	}
60	
61	/** Reactive event boost — applied when a CE event matches */
62	export interface EventBoost {
63	  /** Which event types trigger this boost */
64	  eventTypes: string[];
65	  /** Score bonus added (typically 0.3-0.5, pushes past auto threshold) */
66	  boost: number;
67	  /** Only apply if NPC has a close relationship with the victim */
68	  requiresRelationToVictim?: boolean;
69	}
