71	/**
72	 * Declarative step template for goal building.
73	 * Location fields: '$target' | '$home' | '$extra.KEY' | literal string.
74	 * TargetId fields: '$target' | literal string.
75	 * String fields (purpose, message, reason): interpolation with {varName:fallback}.
76	 * Variables: targetName, targetId, targetLocation, reason, perpetratorName, affectedName,
77	 *   crimeLocation, crimeType, relationship, relationshipDesc, + all target.extra keys.
78	 */
79	export interface StepTemplate {
80	  action: string;
81	  /** Location reference: '$target', '$home', '$extra.KEY', or literal */
82	  location?: string;
83	  /** Target NPC: '$target' or literal id */
84	  targetId?: string;
85	  /** Purpose template with {var:fallback} interpolation */
86	  purpose?: string;
87	  /** Announce message template with {var:fallback} interpolation */
88	  message?: string;
89	  importance?: number;
90	  ticks?: number;
91	  /** Attack reason template */
92	  reason?: string;
93	  lethal?: boolean;
94	  filter?: NpcFilter;
95	  /** Only add this step if NPC is NOT already at the resolved location */
96	  skipIfAt?: boolean;
97	  /** After interaction, transfer relevant crime beliefs between participants */
98	  beliefTransfer?: boolean;
99	  /** Direction of belief transfer: 'target-to-owner' (default) or 'owner-to-target' (for testify) */
100	  beliefTransferDirection?: 'target-to-owner' | 'owner-to-target';
101	  /** After interaction, evaluate if target is a suspect and update confidence based on guilt + H trait */
102	  evaluateSuspect?: boolean;
103	  /** If set, emit an event with this type after interaction (e.g. module-specific event types) */
104	  emitEventType?: string;
105	}
106	
107	export interface BeliefModifier {
108	  /** Match beliefs by eventType (e.g. 'NPC_KILLED', 'GOODS_STOLEN') */
109	  eventType: string;
110	  /** Weight multiplied by max matching belief's confidence (0-1) */
111	  weight: number;
112	}
113	
114	export interface AffordanceDefinition {
115	  id: string;
116	  label: string;
117	  category: string;
118	  severity: number;                // 1-10, for witness reactions
119	  requires: AffordanceRequirement;
120	  weights: AffordanceWeight[];
121	  /** How much negative mood contributes to score (0-1) */
122	  moodWeight: number;
123	  /** How much negative sentiment toward target contributes (0-1) */
124	  relationshipWeight: number;
125	  /** Base probability roll — prevents every-tick firing (proactive only) */
126	  /** Goal type string for NpcGoal */
127	  goalType: string;
128	  /** Goal priority for NpcGoal */
129	  goalPriority: number;
130	  /** Reactive: boost when these events affect the NPC */
131	  eventBoost?: EventBoost;
132	  /** Declarative step templates — replaces switch/case in buildSteps */
133	  stepTemplates?: StepTemplate[];
134	  /** Target finder key — defaults to affordance id. Allows reuse of finders across affordances */
135	  targetFinder?: string;
136	  /** Generic role-based target finding: find nearest NPC with this role (replaces custom finders for simple role lookups) */
137	  targetRole?: string;
138	  /** Situational modifiers: NPC's beliefs boost affordance score */
139	  beliefModifiers?: BeliefModifier[];
140	  /** If true, this affordance is suppressed when player is at the same location */
141	  suppressNearPlayer?: boolean;
142	  /** If true, this is a duty action — blocks 'talk' in urge tier */
143	  isDuty?: boolean;
144	  /** Verb for LLM DO/WHY prompt (e.g. 'steal'). Defaults to id */
145	  actionVerb?: string;
146	  /** Description for LLM action list (e.g. 'steal from their shop') */
147	  actionDescription?: string;
148	  /** If affordance passes requirements, score is at least this value.
149	   *  Use to ensure critical affordances reach reflex tier (≥0.7) when conditions are met. */
150	  minimumScore?: number;
151	  /** Per-affordance cooldown override in game minutes. If set, overrides global affordanceCooldownMinutes. */
152	  cooldownOverride?: number;
153	  /** Personality traits that resist this action — drives internal conflict in instinct description.
154	   *  direction 'high' = high trait resists (e.g. honesty:high resists steal). */
155	  resistTraits?: Array<{ trait: 'openness' | 'conscientiousness' | 'extraversion' | 'agreeableness' | 'neuroticism' | 'honesty'; direction: 'high' | 'low' }>;
156	  /** Trust contribution to scoring. Negative = trust inhibits (crime: -0.1). Positive = trust boosts (duty: 0.05). */
157	  trustWeight?: number;
158	  /** Situational context template for instinct description. Interpolated with target.extra vars.
159	   *  Grounds abstract emotional instinct in concrete situation. E.g. "You know that {targetName} {secretDetail:has a secret}." */
160	  instinctContext?: string;
161	  /** If true, this affordance is social-only (e.g. socialize). Engine uses this flag
162	   *  instead of checking affordance IDs — keeps engine module-agnostic. */
163	  socialOnly?: boolean;
164	}
