166	// ─── Mutable Registries (populated by modules at startup) ───
167	
168	/** Affordance registry — modules push their definitions here */
169	export const AFFORDANCE_REGISTRY: AffordanceDefinition[] = [];
170	
171	// ─── Evaluation Context ───
172	
173	export interface AffordanceContext {
174	  agents: Map<string, Agent>;
175	  locations: LocationGraph;
176	  npcHomes: Map<string, string>;
177	  period: TimePeriod;
178	  gameDay: number;
179	  /** Current absolute game minute (grows indefinitely, minuteOfDay = gameMinute % 1440) */
180	  gameMinute: number;
181	  playerLocation?: string;
182	  hasActiveGoal: (id: string) => boolean;
183	  hasActiveGoalAbove: (id: string, minPriority: number) => boolean;
184	  /** Affordance cooldowns: npcId → affordanceId → expiresAtMinute */
185	  cooldowns?: Map<string, Map<string, number>>;
186	  /** Decision cooldowns: npcId → expiresAtMinute (limits LLM call frequency) */
187	  decisionCooldowns?: Map<string, number>;
188	  /** Configurable cooldown values (from WorldConfig, in game minutes) */
189	  affordanceCooldownMinutes?: number;
190	  decisionCooldownMinutes?: number;
191	  /** Check if NPC is target of someone else's arrest/pursuit goal */
192	  isArrestTarget?: (npcId: string) => boolean;
193	  /** Check if conversation pair is on cooldown (scheduler-managed) */
194	  isPairOnCooldown?: (a: string, b: string) => boolean;
195	  /** LLM temperature for volition decisions (default: 0.35) */
196	  volitionTemperature?: number;
197	}
