215	// ─── Target Finder Registries (populated by modules) ───
216	
217	export type TargetFinderFn = (npcId: string, agent: Agent, ctx: AffordanceContext, aff: AffordanceDefinition) => AffordanceTarget | null;
218	export type ReactiveTargetFinderFn = (npcId: string, agent: Agent, ctx: AffordanceContext, event: WorldEvent, aff: AffordanceDefinition) => AffordanceTarget | null;
219	
220	/** Proactive target finders — keyed by affordance id or targetFinder override */
221	export const TARGET_FINDERS: Map<string, TargetFinderFn> = new Map();
222	
223	/** Reactive target finders — keyed by affordance id or targetFinder override */
224	export const REACTIVE_TARGET_FINDERS: Map<string, ReactiveTargetFinderFn> = new Map();
225	
226	// ─── Requirement Checker Hooks (populated by modules) ───
227	
228	/** Module-provided requirement checkers. Key = requirement field name */
229	export const REQUIREMENT_CHECKERS: Map<string, (agent: Agent, ctx: AffordanceContext, params?: Record<string, unknown>) => boolean> = new Map();
230	
231	// ─── Blocking Goal Types (populated by modules) ───
232	
233	/** Goal types that prevent volition re-evaluation of the target NPC */
234	const BLOCKING_GOAL_TYPES: Set<string> = new Set();
235	
236	export function registerBlockingGoalTypes(types: string[]): void {
237	  for (const t of types) BLOCKING_GOAL_TYPES.add(t);
238	}
239	
240	export function getBlockingGoalTypes(): ReadonlySet<string> {
241	  return BLOCKING_GOAL_TYPES;
242	}
243	
244	// ─── Universal Role-Based Finder (proximity-aware, enriches with crime beliefs) ───
245	
246	export function findByRole(role: string, npcId: string, agent: Agent, ctx: AffordanceContext): AffordanceTarget | null {
247	  type Candidate = { id: string; name: string; location: string; distance: number };
248	  const candidates: Candidate[] = [];
249	
250	  for (const [otherId, other] of ctx.agents) {
251	    if (otherId === npcId || !other.state.alive) continue;
252	    if (isStatusAbsent(other.state.status)) continue;
253	    if (other.profile.role === role) {
254	      let distance: number;
255	      if (other.state.location === agent.state.location) {
256	        distance = 0;
257	      } else {
258	        const loc = ctx.locations.get(agent.state.location);
259	        distance = loc?.connections.includes(other.state.location) ? 1 : 2;
260	      }
261	      candidates.push({ id: otherId, name: other.profile.name, location: other.state.location, distance });
262	    }
263	  }
264	
265	  if (candidates.length === 0) return null;
266	  candidates.sort((a, b) => a.distance - b.distance);
267	  const best = candidates[0];
268	
269	  // Enrich with crime details from NPC's own beliefs (universal — harmless if no beliefs)
270	  const extra: Record<string, string> = {};
271	  const beliefs = agent.state.beliefs?.getAllBeliefs() ?? [];
272	  const crimeBelief = beliefs.find(
273	    (b: Belief) => isTransferable(b.eventType) && b.confidence >= 0.3,
274	  );
275	  if (crimeBelief) {
276	    if (crimeBelief.subject) { extra.perpetratorName = crimeBelief.subject; }
277	    if (crimeBelief.object) extra.affectedName = crimeBelief.object;
278	    if (crimeBelief.location) extra.crimeLocation = crimeBelief.location;
279	    extra.crimeType = getEventLabelSafe(crimeBelief.eventType);
280	  }
281	
282	  return { targetId: best.id, targetName: best.name, targetLocation: best.location, extra };
283	}
284	
285	// ─── Requirement Checking ───
286	
287	/** Generic iteration over all REQUIREMENT_CHECKERS registry entries */
288	function checkRegistryRequirements(req: AffordanceRequirement, agent: Agent, ctx: AffordanceContext): boolean {
289	  const reqRecord = req as Record<string, unknown>;
290	  for (const [key, checker] of REQUIREMENT_CHECKERS) {
291	    if (!reqRecord[key]) continue;
292	    // Pass affordance-level params (e.g. beliefConfidence for hasCrimeBelief)
293	    const params: Record<string, unknown> = {};
294	    if (req.beliefConfidence !== undefined) params.minConfidence = req.beliefConfidence;
295	    if (!checker(agent, ctx, params)) return false;
296	  }
297	  return true;
298	}
299	
300	/** Post-target checks: noGuardNearby, maxWitnesses, sentimentBelow */
301	function checkPostTargetRequirements(req: AffordanceRequirement, npcId: string, target: AffordanceTarget, ctx: AffordanceContext): boolean {
302	  if (req.noGuardNearby) {
303	    for (const [, other] of ctx.agents) {
304	      if (!other.state.alive) continue;
305	      if (other.profile.detersCrime && other.state.location === target.targetLocation) return false;
306	    }
307	  }
308	  if (req.maxWitnesses !== undefined) {
309	    let witnessCount = 0;
310	    for (const [otherId, other] of ctx.agents) {
311	      if (otherId === npcId || otherId === target.targetId) continue;
312	      if (!other.state.alive) continue;
313	      if (other.state.location === target.targetLocation) witnessCount++;
314	    }
315	    if (witnessCount > req.maxWitnesses) return false;
316	  }
317	  if (req.sentimentBelow !== undefined) {
318	    const rel = ctx.agents.get(npcId)?.state.relationships?.getRelationship(target.targetId);
319	    if (!rel || rel.sentiment >= req.sentimentBelow) return false;
320	  }
321	  return true;
322	}
323	
324	export function checkRequirements(
325	  aff: AffordanceDefinition,
326	  npcId: string,
327	  agent: Agent,
328	  ctx: AffordanceContext,
329	): AffordanceTarget | null {
330	  const req = aff.requires;
331	
332	  if (req.notGuard && agent.profile.investigator) return null;
333	  if (req.isGuard && !agent.profile.investigator) return null;
334	  if (req.isInvestigator && !agent.profile.investigator) return null;
335	  if (req.canSentence && !agent.profile.canSentence) return null;
336	  if (req.period && !req.period.includes(ctx.period)) return null;
337	  if (req.moodBelow !== undefined && agent.state.mood >= req.moodBelow) return null;
338	  if (aff.suppressNearPlayer && ctx.playerLocation === agent.state.location) return null;
339	
340	  // Module-provided requirement checks — generic iteration over registry
341	  if (!checkRegistryRequirements(req, agent, ctx)) return null;
342	
343	  const target = findTarget(aff, npcId, agent, ctx);
344	  if (!target) return null;
345	
346	  if (!checkPostTargetRequirements(req, npcId, target, ctx)) return null;
347	
348	  return target;
349	}
