351	/**
352	 * Relaxed requirement check for reactive evaluation.
353	 * Skips mood threshold (event urgency overrides mood gate).
354	 * All other requirements are enforced.
355	 */
356	export function checkRequirementsReactive(
357	  aff: AffordanceDefinition,
358	  npcId: string,
359	  agent: Agent,
360	  ctx: AffordanceContext,
361	  event: WorldEvent,
362	): AffordanceTarget | null {
363	  const req = aff.requires;
364	
365	  if (req.notGuard && agent.profile.investigator) return null;
366	  if (req.isGuard && !agent.profile.investigator) return null;
367	  if (req.isInvestigator && !agent.profile.investigator) return null;
368	  if (req.canSentence && !agent.profile.canSentence) return null;
369	  if (req.period && !req.period.includes(ctx.period)) return null;
370	  // mood intentionally skipped for reactive (event urgency overrides mood gate)
371	  if (aff.suppressNearPlayer && ctx.playerLocation === agent.state.location) return null;
372	
373	  // Module-provided requirement checks — generic iteration over registry
374	  if (!checkRegistryRequirements(req, agent, ctx)) return null;
375	
376	  const target = findReactiveTarget(aff, npcId, agent, ctx, event);
377	  if (!target) return null;
378	
379	  if (!checkPostTargetRequirements(req, npcId, target, ctx)) return null;
380	
381	  return target;
382	}
