384	// ─── Target Finding (Proactive) ───
385	
386	function findTarget(
387	  aff: AffordanceDefinition,
388	  npcId: string,
389	  agent: Agent,
390	  ctx: AffordanceContext,
391	): AffordanceTarget | null {
392	  // Generic role-based finder takes priority (declarative, no custom code needed)
393	  if (aff.targetRole) return findByRole(aff.targetRole, npcId, agent, ctx);
394	  const key = aff.targetFinder ?? aff.id;
395	  const finder = TARGET_FINDERS.get(key);
396	  return finder ? finder(npcId, agent, ctx, aff) : null;
397	}
398	
399	// ─── Target Finding (Reactive — uses event data) ───
400	
401	function findReactiveTarget(
402	  aff: AffordanceDefinition,
403	  npcId: string,
404	  agent: Agent,
405	  ctx: AffordanceContext,
406	  event: WorldEvent,
407	): AffordanceTarget | null {
408	  // Check reactive registry first (registered by affordance id, not targetFinder)
409	  const finder = REACTIVE_TARGET_FINDERS.get(aff.id);
410	  if (finder) return finder(npcId, agent, ctx, event, aff);
411	  // Fallback to generic role-based finder
412	  if (aff.targetRole) return findByRole(aff.targetRole, npcId, agent, ctx);
413	  return null;
414	}
415	
416	// ─── Utility Scoring ───
417	
418	const TRAIT_MAP: Record<OceanHTrait, keyof Agent['profile']['bigFive']> = {
419	  O: 'openness', C: 'conscientiousness', E: 'extraversion',
420	  A: 'agreeableness', N: 'neuroticism', H: 'honesty',
421	};
422	
423	/**
424	 * Non-linear mood curve — 3 psychological zones:
425	 * - Sliding (-0.3 to -0.6): most volatile, ×1.5 multiplier (desperation onset)
426	 * - Desperation (-0.6 to -0.8): sustained high contribution, ×1.0
427	 * - Numbness (-0.8 to -1.0): reduced effect ×0.6 (apathy, not action)
428	 * - Positive mood: returns negative value (inhibits crime, enables social)
429	 */
430	function moodCurve(mood: number, H: number = 0.5): number {
431	  if (mood >= 0) return -mood * 0.3; // positive mood → negative score (inhibits)
432	
433	  // Personality-shifted zones (SPEC-mood-modifiers):
434	  // Low H → enters sliding zone earlier (more crime-prone)
435	  const slidingEntry = 0.30 - (1 - H) * 0.20; // H=0.2: 0.14, H=0.5: 0.20, H=0.9: 0.28
436	  const desperationEntry = slidingEntry + 0.30;
437	  const numbnessEntry = slidingEntry + 0.50;
438	
439	  const absMood = -mood; // 0 to 1
440	  if (absMood <= slidingEntry) return absMood * (0.15 / slidingEntry); // continuous at boundary: slidingEntry * 0.15/slidingEntry = 0.15
441	  if (absMood <= desperationEntry) return 0.15 + (absMood - slidingEntry) * 1.5; // sliding zone — ×1.5
442	  if (absMood <= numbnessEntry) return 0.60 + (absMood - desperationEntry) * 1.0; // desperation
443	  return 0.80 + (absMood - numbnessEntry) * 0.6; // numbness plateau
444	}
445	
446	/**
447	 * Non-linear sentiment curve — mirrors mood zones:
448	 * - Mild irritation (0 to -0.3): ×0.5
449	 * - Active hostility (-0.3 to -0.6): ×1.5
450	 * - Dehumanization (-0.6 to -1.0): ×0.8 (already decided, less incremental)
451	 * - Positive sentiment: returns negative value (inhibits harm, enables cooperation)
452	 */
453	function sentimentCurve(sentiment: number): number {
454	  if (sentiment >= 0) return -sentiment * 0.3; // positive → inhibits harm
455	  const absSent = -sentiment;
456	  if (absSent <= 0.3) return absSent * 0.5;
457	  if (absSent <= 0.6) return 0.15 + (absSent - 0.3) * 1.5;
458	  return 0.60 + (absSent - 0.6) * 0.8;
459	}
460	
461	export function computeUtility(aff: AffordanceDefinition, agent: Agent, target: AffordanceTarget): number {
462	  // 1. Personality (OCEAN+H weights)
463	  let personalityScore = 0;
464	  for (const w of aff.weights) {
465	    const traitValue = agent.profile.bigFive[TRAIT_MAP[w.trait]];
466	    const effective = w.direction === 'high' ? traitValue : (1 - traitValue);
467	    personalityScore += w.multiplier * effective;
468	  }
469	
470	  // 2. Mood (non-linear, bidirectional)
471	  const moodContribution = aff.moodWeight * moodCurve(agent.state.mood, agent.profile.bigFive.honesty);
472	
473	  // 3. Relationship (non-linear, bidirectional)
474	  let relationshipContribution = 0;
475	  const rel = agent.state.relationships?.getRelationship(target.targetId);
476	  if (rel) {
477	    relationshipContribution = aff.relationshipWeight * sentimentCurve(rel.sentiment);
478	  }
479	
480	  // 4. Situational: beliefs boost score based on what NPC knows
481	  let situationalContribution = 0;
482	  if (aff.beliefModifiers && agent.state.beliefs) {
483	    const beliefs = agent.state.beliefs.getAllBeliefs();
484	    for (const mod of aff.beliefModifiers) {
485	      let maxConfidence = 0;
486	      for (const b of beliefs) {
487	        if (b.eventType === mod.eventType && b.confidence > maxConfidence) {
488	          maxConfidence = b.confidence;
489	        }
490	      }
491	      situationalContribution += mod.weight * maxConfidence;
492	    }
493	  }
494	
495	  // 5. Trust (direction from affordance data: negative = inhibits, positive = boosts)
496	  const trustContribution = (rel && aff.trustWeight) ? aff.trustWeight * rel.trust : 0;
497	
498	  const rawScore = personalityScore + moodContribution + relationshipContribution + situationalContribution + trustContribution;
499	  const clamped = Math.max(0, Math.min(1, rawScore));
500	  return aff.minimumScore ? Math.max(clamped, aff.minimumScore) : clamped;
501	}
502	
503	// ─── Player Action Validation ───
504	
505	export interface ValidationResult {
506	  allowed: boolean;
507	  /** Human-readable reason if not allowed */
508	  reason?: string;
509	  /** The matched affordance definition */
510	  affordance?: AffordanceDefinition;
511	  /** Resolved target */
512	  target?: AffordanceTarget;
513	}
514	
515	/**
516	 * Validate whether a player can perform an action.
517	 * Checks affordance requirements without personality/LLM scoring.
518	 * AL for Player = validator (can you do this?), not generator (what should you do?).
519	 */
520	export function validatePlayerAction(
521	  actionId: string,
522	  playerId: string,
523	  playerAgent: Agent,
524	  ctx: AffordanceContext,
525	  targetId?: string,
526	): ValidationResult {
527	  const aff = AFFORDANCE_REGISTRY.find((a) => a.id === actionId);
528	  if (!aff) {
529	    return { allowed: false, reason: `Unknown action: ${actionId}` };
530	  }
531	
532	  // Check basic requirements (skip personality-based ones like mood/sentiment)
533	  const req = aff.requires;
534	  if (req.period && !req.period.includes(ctx.period)) {
535	    return { allowed: false, reason: `Cannot ${actionId} during ${ctx.period}`, affordance: aff };
536	  }
537	  if (req.isInvestigator && !playerAgent.profile.investigator) {
538	    return { allowed: false, reason: `Only investigators can ${actionId}`, affordance: aff };
539	  }
540	  if (req.canSentence && !playerAgent.profile.canSentence) {
541	    return { allowed: false, reason: `Only judges can ${actionId}`, affordance: aff };
542	  }
543	
544	  // Module requirement checks
545	  for (const [key, checker] of REQUIREMENT_CHECKERS) {
546	    if ((req as Record<string, unknown>)[key] && !checker(playerAgent, ctx)) {
547	      return { allowed: false, reason: `Requirement not met: ${key}`, affordance: aff };
548	    }
549	  }
550	
551	  // If specific target provided, validate co-location
552	  if (targetId) {
553	    const target = ctx.agents.get(targetId);
554	    if (!target) {
555	      return { allowed: false, reason: `Target not found: ${targetId}`, affordance: aff };
556	    }
557	    if (!target.state.alive) {
558	      return { allowed: false, reason: `${target.profile.name} is dead`, affordance: aff };
559	    }
560	    if (playerAgent.state.location !== target.state.location) {
561	      return { allowed: false, reason: `${target.profile.name} is not here`, affordance: aff };
562	    }
563	    return {
564	      allowed: true,
565	      affordance: aff,
566	      target: {
567	        targetId,
568	        targetName: target.profile.name,
569	        targetLocation: target.state.location,
570	      },
571	    };
572	  }
573	
574	  return { allowed: true, affordance: aff };
575	}
