125	// ─── Proactive Entry Point (each tick) ───
126	
127	export async function evaluateAllVolition(
128	  ctx: AffordanceContext,
129	  onLlmCall?: (label: string, detail: string) => void,
130	  onDecision?: (data: { npcId: string; npcName: string; action: string; target?: string; reason: string; topScore: number; instinctTier: string; alternatives: { verb: string; score: number }[] }) => void,
131	  /** Optional: only evaluate these NPC IDs. If omitted, evaluates all eligible. */
132	  npcFilter?: string[],
133	): Promise<NpcGoal[]> {
134	  const goals: NpcGoal[] = [];
135	  const filterSet = npcFilter ? new Set(npcFilter) : null;
136	
137	  for (const [npcId, agent] of ctx.agents) {
138	    if (filterSet && !filterSet.has(npcId)) continue;
139	    if (agent.profile.isPlayer) continue; // Player makes own decisions
140	    if (agent.state.inPlayerChat) continue; // NPC frozen in conversation with player
141	    if (!agent.state.alive || isStatusAbsent(agent.state.status)) continue;
142	    if (ctx.hasActiveGoalAbove(npcId, 4)) continue;
143	    if (ctx.isArrestTarget?.(npcId)) continue; // someone is arresting this NPC — skip evaluation
144	
145	    // Decision cooldown — don't re-evaluate too frequently
146	    if (ctx.decisionCooldowns) {
147	      const expires = ctx.decisionCooldowns.get(npcId);
148	      if (expires !== undefined && ctx.gameMinute < expires) continue;
149	    }
150	
151	    // Evaluate all affordances proactively (including those with eventBoost — NPC may have beliefs to act on)
152	    const npcCooldowns = ctx.cooldowns?.get(npcId);
153	    const scored: ScoredAffordance[] = [];
154	    for (const aff of AFFORDANCE_REGISTRY) {
155	      // Skip if on affordance cooldown
156	      if (npcCooldowns) {
157	        const expires = npcCooldowns.get(aff.id);
158	        if (expires !== undefined && ctx.gameMinute < expires) continue;
159	      }
160	      const target = checkRequirements(aff, npcId, agent, ctx);
161	      if (!target) continue;
162	      const score = computeUtility(aff, agent, target);
163	      if (score < MIN_SCORE) continue;
164	      scored.push({ definition: aff, score, target });
165	    }
166	
167	    // No affordances available → skip LLM call (NPC follows schedule)
168	    if (scored.length === 0) {
169	      if (agent.profile.investigator) {
170	        console.log(`  [AL:debug] ${agent.profile.name}: no affordances passed (beliefs: ${agent.state.beliefs?.getAllBeliefs().length ?? 0})`);
171	      }
172	      continue;
173	    }
174	    scored.sort((a, b) => b.score - a.score);
175	    console.log(`  [AL:debug] ${agent.profile.name}: ${scored.length} affordances → ${scored.map(s => `${s.definition.id}:${s.score.toFixed(2)}`).join(', ')}`);
176	
177	    // ── ALL decisions through LLM — instinct builder provides pressure, NPC always has final say ──
178	    const goal = await llmDecideAndBuild(scored, npcId, agent, ctx, onLlmCall, onDecision);
179	
180	    if (goal) {
181	      goal.createdAtMinute = ctx.gameMinute;
182	      goals.push(goal);
183	      setDecisionCooldown(ctx, npcId, ctx.gameMinute);
184	      const affDef = AFFORDANCE_REGISTRY.find(a => a.id === goal.data?.affordanceId);
185	      setAffordanceCooldown(ctx, npcId, goal.data?.affordanceId as string, ctx.gameMinute, affDef);
186	    } else {
187	      // NPC chose "wait" or system rejected — apply extended cooldown only if not already set
188	      // (pair cooldown rejection sets a shorter cooldown directly in intentionToGoal)
189	      const existing = ctx.decisionCooldowns?.get(npcId) ?? 0;
190	      if (existing <= ctx.gameMinute) {
191	        setDecisionCooldownExtended(ctx, npcId, ctx.gameMinute);
192	      }
193	    }
194	  }
195	
196	  return goals;
197	}
