672	/** Exact case-insensitive match against a list of valid names */
673	function matchName(input: string, validNames: string[]): string | null {
674	  if (!input) return null;
675	  const lower = input.toLowerCase();
676	  // Exact match
677	  const exact = validNames.find((n) => n.toLowerCase() === lower);
678	  if (exact) return exact;
679	  // Fuzzy: input contains a valid name (e.g. "Garrett and Traveler" → "Garrett")
680	  const sorted = [...validNames].sort((a, b) => b.length - a.length);
681	  for (const name of sorted) {
682	    if (lower.includes(name.toLowerCase())) return name;
683	  }
684	  return null;
685	}
