197	function getResistanceVoice(
198	  resistTraits: Array<{ trait: keyof BigFiveTraits; direction: 'high' | 'low' }> | undefined,
199	  bigFive: { openness: number; conscientiousness: number; extraversion: number; agreeableness: number; neuroticism: number; honesty: number },
200	): string {
201	  if (!resistTraits || resistTraits.length === 0) return '';
202	
203	  const parts: string[] = [];
204	  for (const rt of resistTraits) {
205	    const traitValue = bigFive[rt.trait];
206	    // direction 'high' means high trait resists → use trait value directly
207	    // direction 'low' means low trait resists → use 1-traitValue
208	    const effectiveValue = rt.direction === 'high' ? traitValue : (1 - traitValue);
209	
210	    const traitKey = `${rt.trait.charAt(0).toUpperCase()}_${rt.direction}`;
211	    const thresholds = RESISTANCE_TEMPLATES[traitKey];
212	    if (!thresholds) continue;
213	
214	    // Find highest matching threshold
215	    let text = '';
216	    for (const t of thresholds) {
217	      if (effectiveValue >= t.min) text = t.text;
218	    }
219	    if (text) parts.push(text);
220	  }
221	
222	  return parts.length > 0 ? parts.join(' ') : '';
223	}
