227	function getEscalationPrefix(count: number): string {
228	  if (count <= 0) return '';
229	  if (count <= 2) return 'The thought has visited before.';
230	  if (count <= 4) return 'Again. Like an old companion you can\'t shake.';
231	  return 'It\'s no longer a thought. It lives in you now. Patient. Always waiting.';
232	}
