234	// ─── Mood coloring ───
235	
236	function getMoodColoring(mood: number, tier: number): string {
237	  // Only add mood coloring at significant intensity + negative mood
238	  if (tier < 2 || mood > -0.2) return '';
239	  if (mood > -0.4) return 'A tightness behind your eyes.';
240	  if (mood > -0.7) return 'Your hands are unsteady. How long since you slept properly?';
241	  return 'The world has gone flat and grey. You barely recognize your own thoughts.';
242	}
