244	// ─── Main builder ───
245	
246	export function buildInstinctDescription(
247	  input: InstinctInput,
248	  profile: AgentProfile,
249	  mood: number,
250	): string {
251	  const tier = getIntensityTier(input.score);
252	  const sevClass = getSeverityClass(input.severity);
253	
254	  // 1. Base intensity × texture
255	  const base = TEMPLATES[sevClass][tier];
256	
257	  // 2. Enneagram motivation (only at tier 2+ — below that, motivation hasn't crystallized)
258	  let motivation = '';
259	  if (tier >= 2 && profile.enneagram) {
260	    const drives = ENNEAGRAM_DRIVE[profile.enneagram.type];
261	    if (drives) {
262	      motivation = drives[sevClass] || '';
263	    }
264	  }
265	
266	  // 3. Resistance from opposing traits (always present if traits oppose)
267	  const resistance = getResistanceVoice(
268	    input.resistTraits,
269	    profile.bigFive,
270	  );
271	
272	  // 4. Escalation prefix
273	  const escalation = getEscalationPrefix(input.considerationCount);
274	
275	  // 5. Mood coloring
276	  const moodColor = getMoodColoring(mood, tier);
277	
278	  // Compose: [escalation] base [context] [motivation] [resistance] [mood]
279	  // Flow: emotional intensity → situational grounding → enneagram drive → counter-voice → physical state
280	  const parts = [escalation, base, input.context, motivation, resistance, moodColor].filter(Boolean);
281	  return parts.join(' ');
282	}
