285	
286	const TIER_NAMES = ['whisper', 'echo', 'temptation', 'grip', 'flood', 'torrent', 'abyss'];
287	
288	export function getTierName(score: number): string {
289	  return TIER_NAMES[getIntensityTier(score)] || 'unknown';
290	}
