1	// EventType is a string — modules define their event types via registries.
2	// No hardcoded union — engine is content-agnostic.
3	export type EventType = string;
4	
5	export interface WorldEvent {
6	  id: string;
7	  type: EventType;
8	  subject: string;        // who did it (entity id)
9	  object?: string;        // target entity id
10	  location: string;
11	  gameDay: number;
12	  importance: number;
13	  payload: Record<string, unknown>;
14	}
15	
16	export interface ConsequenceRule {
17	  id: string;
18	  trigger: EventType;
19	  conditions: RuleCondition[];
20	  consequence: {
21	    type: EventType;
22	    importance: number;
23	    delayDays: number;
24	    probability: number;
25	  };
26	  maxChainDepth: number;
27	  /** If true, the subject of beliefs created from this rule's consequence should be null (discoverer doesn't know perpetrator) */
28	  subjectUnknown?: boolean;
29	  /** If true, targets of this rule are tracked as witnesses (for body discovery dedup) */
30	  tracksWitness?: boolean;
31	  /** How to select initial target candidates. Default: 'affected' */
32	  targetMode?: 'witnesses' | 'location' | 'affected' | 'all';
33	  /** Exclusive group name. Rules in same group: only highest-priority match fires per target set. */
34	  exclusive?: string;
35	  /** Priority within exclusive group. Higher = wins. Default 0. */
36	  priority?: number;
37	}
38	
39	export interface RuleCondition {
40	  field?: string;          // for eq/gt/lt on event payload
41	  op: string;              // 'trait', 'relationship', 'belief', 'has_capability', 'is_public_place', 'eq', 'gt', 'lt'
42	  value?: unknown;
43	  // ─── NPC-state condition fields (CG v2) ───
44	  /** Whose state to check: target (filter), subject/object (gate) */
45	  of?: 'target' | 'subject' | 'object';
46	  /** For op='trait': which OCEAN+H trait */
47	  trait?: string;
48	  /** For op='relationship': who feels */
49	  actor?: 'target' | 'subject' | 'object';
50	  /** For op='relationship': toward whom (role ref or payload field name) */
51	  toward?: string;
52	  /** Numeric comparator for trait/relationship */
53	  comparator?: '>' | '<' | '>=' | '<=';
54	  /** For op='belief': filter by event type */
55	  eventType?: string;
56	  /** For op='belief': minimum confidence threshold */
