185	  /**
186	   * Resolve initial target candidates based on rule.targetMode.
187	   * - 'witnesses': alive agents at event location, excluding subject/object/known witnesses
188	   * - 'location': all alive agents at event location, excluding known witnesses
189	   * - 'affected': event.payload.affectedTargets (default, for chain rules)
190	   * - 'all': all alive agents
191	   */
192	  private resolveTargets(rule: ConsequenceRule, event: WorldEvent, ctx: WorldContext): string[] {
193	    const mode = rule.targetMode ?? 'affected';
194	
195	    switch (mode) {
196	      case 'witnesses':
197	        return Array.from(ctx.agents.entries())
198	          .filter(([id, agent]) =>
199	            agent.state.alive &&
200	            agent.state.location === event.location &&
201	            id !== event.object &&
202	            id !== event.subject &&
203	            !ctx.witnessIds?.has(id),
204	          )
205	          .map(([id]) => id);
206	
207	      case 'location':
208	        return Array.from(ctx.agents.entries())
209	          .filter(([id, agent]) =>
210	            agent.state.alive &&
211	            agent.state.location === event.location &&
212	            !ctx.witnessIds?.has(id),
213	          )
214	          .map(([id]) => id);
215	
216	      case 'affected':
217	        return (event.payload?.affectedTargets as string[]) ?? [];
218	
219	      case 'all':
220	        return Array.from(ctx.agents.entries())
221	          .filter(([, agent]) => agent.state.alive)
222	          .map(([id]) => id);
223	    }
224	  }
225	
226	  /**
227	   * Determine if a condition is a gate (check once, fail entire rule)
228	   * or a filter (reduce candidate list per-target).
229	   * Gate = condition references event/subject/object, not individual targets.
230	   * Filter = condition references 'target' → applied to each candidate.
231	   */
232	  private isGateCondition(cond: RuleCondition): boolean {
233	    // Event payload checks are always gates
234	    if (cond.op === 'eq' || cond.op === 'gt' || cond.op === 'lt') return true;
235	    if (cond.op === 'is_public_place') return true;
236	    // NPC-state conditions: gate if checking subject/object, filter if checking target
237	    // Default: 'target' (filter) — missing 'of'/'actor' = per-target check, not gate
238	    if (cond.op === 'trait') return (cond.of ?? 'target') !== 'target';
239	    if (cond.op === 'relationship') return (cond.actor ?? 'target') !== 'target';
240	    if (cond.op === 'belief') return (cond.of ?? 'target') !== 'target';
241	    // has_capability is always a filter (checks each target)
242	    if (cond.op === 'has_capability') return false;
243	    return false;
244	  }
245	
246	  private evaluateGate(cond: RuleCondition, event: WorldEvent, ctx: WorldContext): boolean {
247	    if (cond.op === 'is_public_place') {
248	      return ctx.publicPlaces?.has(event.location) ?? false;
249	    }
250	
251	    // Event payload comparisons
252	    if (cond.op === 'eq' || cond.op === 'gt' || cond.op === 'lt') {
253	      const fieldValue = (event as unknown as Record<string, unknown>)[cond.field!];
254	      if (cond.op === 'eq') return fieldValue === cond.value;
255	      if (cond.op === 'gt') return (fieldValue as number) > (cond.value as number);
256	      if (cond.op === 'lt') return (fieldValue as number) < (cond.value as number);
257	    }
258	
259	    // NPC-state gates (of !== 'target')
260	    if (cond.op === 'trait' && cond.of !== 'target') {
261	      const agent = this.resolveActor(cond.of!, event, ctx);
262	      return agent ? this.checkTrait(agent, cond) : false;
263	    }
264	    if (cond.op === 'relationship' && cond.actor !== 'target') {
265	      const agent = this.resolveActor(cond.actor!, event, ctx);
266	      const towardId = this.resolveToward(cond.toward!, event, ctx);
267	      return agent && towardId ? this.checkRelationship(agent, towardId, cond) : false;
268	    }
269	    if (cond.op === 'belief' && cond.of !== 'target') {
270	      const agent = this.resolveActor(cond.of!, event, ctx);
271	      return agent ? this.checkBelief(agent, event, cond) : false;
272	    }
273	
274	    console.warn(`[CG] Unknown gate condition op '${cond.op}'`);
275	    return true; // unknown op = pass (forward compat)
276	  }
277	
278	  private evaluateFilter(cond: RuleCondition, targetId: string, event: WorldEvent, ctx: WorldContext): boolean {
279	    const agent = ctx.agents.get(targetId);
280	    if (!agent) return false;
281	
282	    if (cond.op === 'has_capability') {
283	      const capFlag = (cond.value ?? cond.field) as string;
284	      return !!(agent.profile as unknown as Record<string, unknown>)[capFlag];
285	    }
286	    if (cond.op === 'trait') {
287	      return this.checkTrait(agent, cond);
288	    }
289	    if (cond.op === 'relationship') {
290	      const towardId = this.resolveToward(cond.toward!, event, ctx, targetId);
291	      return towardId ? this.checkRelationship(agent, towardId, cond) : false;
292	    }
293	    if (cond.op === 'belief') {
294	      return this.checkBelief(agent, event, cond);
295	    }
296	
297	    return true; // unknown filter = include (forward compat)
298	  }
