300	  // ─── CG v2: Helper functions ───
301	
302	  private resolveActor(ref: string, event: WorldEvent, ctx: WorldContext): Agent | null {
303	    const id = ref === 'subject' ? event.subject
304	      : ref === 'object' ? event.object
305	      : null;
306	    return id ? ctx.agents.get(id) ?? null : null;
307	  }
308	
309	  private resolveToward(ref: string, event: WorldEvent, ctx: WorldContext, targetId?: string): string | null {
310	    if (ref === 'subject') return event.subject;
311	    if (ref === 'object') return event.object ?? null;
312	    if (ref === 'target') return targetId ?? null;
313	    // Payload field → may be NPC name, resolve to ID
314	    const nameOrId = event.payload?.[ref] as string | undefined;
315	    if (!nameOrId) return null;
316	    if (ctx.agents.has(nameOrId)) return nameOrId;
317	    for (const [id, a] of ctx.agents) {
318	      if (a.profile.name === nameOrId) return id;
319	    }
320	    return null;
321	  }
322	
323	  private checkTrait(agent: Agent, cond: RuleCondition): boolean {
324	    const traitName = cond.trait as string;
325	    const traitValue = (agent.profile.bigFive as unknown as Record<string, number>)[traitName];
326	    if (traitValue == null) return false;
327	    return this.compare(traitValue, cond.comparator ?? '>', cond.value as number);
328	  }
329	
330	  private checkRelationship(agent: Agent, towardId: string, cond: RuleCondition): boolean {
331	    const rel = agent.state.relationships?.getRelationship(towardId);
332	    if (!rel) return false;
333	    const val = (rel as unknown as Record<string, number>)[cond.field ?? 'sentiment'];
334	    if (val == null) return false;
335	    return this.compare(val, cond.comparator ?? '>', cond.value as number);
336	  }
337	
338	  private checkBelief(agent: Agent, event: WorldEvent, cond: RuleCondition): boolean {
339	    if (!agent.state.beliefs) return false;
340	    const beliefs = agent.state.beliefs.getAllBeliefs();
341	    return beliefs.some(b => {
342	      if (cond.eventType && b.eventType !== cond.eventType) return false;
343	      if (cond.minConfidence && b.confidence < cond.minConfidence) return false;
344	      if (cond.aboutSubject && b.subject !== ((event.payload?.perpetratorName as string) ?? event.subject)) return false;
345	      return true;
346	    });
347	  }
348	
349	  private compare(a: number, op: string, b: number): boolean {
350	    switch (op) {
351	      case '>': return a > b;
352	      case '<': return a < b;
353	      case '>=': return a >= b;
354	      case '<=': return a <= b;
355	      default: return a === b;
356	    }
357	  }
